#!/usr/bin/env node
// TEST DOUBLE of stable-diffusion.cpp's `sd-cli` (no model is loaded, nothing is generated by a model): it reads the
// same flags, prints progress lines in the engine's own format, and writes a real PNG of the asked size at `-o`.
// A prompt containing FAKE_OOM makes it fail the way the engine does when memory runs out; FAKE_SLOW makes it take
// about a minute (for cancel and time-limit tests). Each call is appended to $FAKE_SD_LOG (one JSON line of its argv).
import { appendFileSync, writeFileSync } from "node:fs";
import { crc32, deflateSync } from "node:zlib";

const argv = process.argv.slice(2), flag = (name) => { const at = argv.indexOf(name); return at >= 0 ? argv[at + 1] : undefined; };
if (process.env.FAKE_SD_LOG) appendFileSync(process.env.FAKE_SD_LOG, `${JSON.stringify(argv)}\n`);
const width = Number(flag("-W") ?? 512), height = Number(flag("-H") ?? 512), steps = Number(flag("--steps") ?? 20), seed = Number(flag("-s") ?? 42), out = flag("-o") ?? "output.png", prompt = flag("-p") ?? "";
for (const required of ["--diffusion-model", "--vae", "--llm"]) if (!flag(required)) { console.error(`missing ${required}`); process.exit(2); }
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
console.log("[INFO ] stable-diffusion.cpp (test double) loading model");
if (prompt.includes("FAKE_OOM")) { console.error("[ERROR] ggml_metal_buffer_alloc: error: out of memory allocating 6144.00 MiB"); process.exit(1); }
const pace = prompt.includes("FAKE_SLOW") ? 3000 : 5;
for (let step = 1; step <= steps; step++) { await sleep(pace); process.stdout.write(`\r  |${"=".repeat(Math.round((step / steps) * 50)).padEnd(50)}| ${step}/${steps} - 0.01s/it`); }
process.stdout.write("\n");
// A PNG: 8-bit RGB, one colour from the seed (two seeds give two different files).
const chunk = (type, data) => { const length = Buffer.alloc(4); length.writeUInt32BE(data.length); const body = Buffer.concat([Buffer.from(type), data]); const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(body) >>> 0); return Buffer.concat([length, body, crc]); };
const header = Buffer.alloc(13); header.writeUInt32BE(width, 0); header.writeUInt32BE(height, 4); header[8] = 8; header[9] = 2;
const row = Buffer.alloc(1 + width * 3); for (let x = 0; x < width; x++) { row[1 + x * 3] = seed % 256; row[2 + x * 3] = (seed >> 8) % 256; row[3 + x * 3] = 128; }
const raw = Buffer.concat(Array.from({ length: height }, () => row));
writeFileSync(out, Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk("IHDR", header), chunk("IDAT", deflateSync(raw)), chunk("IEND", Buffer.alloc(0))]));
console.log(`[INFO ] save result image to '${out}'`);
